"""Actual normal original model picker and local OBJ upload, including raster."""
import hashlib,json,os,tempfile,unittest
from pathlib import Path
from playwright.sync_api import sync_playwright
ROOT=Path(__file__).resolve().parents[1]
class ModelGalleryBrowser(unittest.TestCase):
 def test_original_sample_upload_full_geometry_and_rejection_rollback(self):
  with sync_playwright()as pw:
   browser=pw.chromium.launch(headless=True);page=browser.new_page(viewport={'width':1440,'height':900});errors=[];page.on('pageerror',lambda e:errors.append(str(e)));page.goto(Path(os.environ.get('NOCTURNE_MODEL_GALLERY_PATH',ROOT/'Nocturne-Test-Harness.html')).resolve().as_uri());page.wait_for_function('window.nativeLab');page.evaluate('nativeLab.hold()');self.assertEqual(page.locator('#scenes option[value="original-orbital-loom"]').count(),1);self.assertEqual(page.locator('#model-file').count(),1);page.select_option('#scenes','original-orbital-loom');page.evaluate('nativeLab.hold()');page.locator('#model-panel').evaluate('(e)=>e.open=true');self.assertEqual(page.evaluate('nativeLab.scene.info().sourceModel.triangles'),4608)
   proof=page.evaluate('()=>{const s=nativeLab.scene,records=s.modelRecords(),saved=s.snapshot(),full=s.render().bytes.slice();s.setModelRecords(records.slice(0,256*40));const short=s.render().bytes.slice();s.setModelRecords(new Uint8Array());const empty=s.render().bytes.slice();s.restore(saved);let prefix=0,none=0;for(let i=0;i<full.length;i+=16){if(full.slice(i,i+12).some((v,k)=>v!==short[i+k]))prefix++;if(full.slice(i,i+12).some((v,k)=>v!==empty[i+k]))none++;}return{records:records.length,prefix,none,pure:s.snapshot().every((v,i)=>v===saved[i])}}');self.assertEqual(proof['records'],4608*40);self.assertGreater(proof['prefix'],100);self.assertGreater(proof['none'],100);self.assertTrue(proof['pure'])
   source=(ROOT/'tests/fixtures/source-model/continuity-example-mesh.mjs').read_text();obj=json.loads(source.split('export const EXAMPLE_OBJ = ',1)[1].strip().rstrip(';'));page.locator('#draft').fill('Original model document e\u0301 🪶');page.locator('#draft').dispatch_event('input');page.locator('#model-file').set_input_files({'name':'Orbital Loom.obj','mimeType':'text/plain','buffer':obj.encode()});page.wait_for_function('document.getElementById("model-status").dataset.fileName==="Orbital Loom.obj"');self.assertEqual(page.evaluate('nativeLab.scene.info().sourceModel.triangles'),4608);self.assertEqual(page.evaluate('nativeLab.scene.info().prompt.text'),'Original model document e\u0301 🪶');page.evaluate("nativeLab.scene.command({op:'schedule',id:900,atUs:2000000,command:{op:'input',text:' queued'}});window.modelSaved=nativeLab.scene.snapshot();window.modelFrame=nativeLab.scene.render().bytes.slice();window.originalModelRecords=nativeLab.scene.modelRecords()");page.locator('#model-file').set_input_files({'name':'bad.obj','mimeType':'text/plain','buffer':b'v 0 0 0\nf 1 2 999\n'});page.wait_for_function('document.getElementById("model-status").dataset.error==="true"');self.assertTrue(page.evaluate('()=>{const a=nativeLab.scene.snapshot(),b=nativeLab.scene.render().bytes;return a.length===modelSaved.length&&a.every((v,i)=>v===modelSaved[i])&&b.every((v,i)=>v===modelFrame[i]);}'));page.locator('#columns').evaluate('(e)=>e.closest("details").open=true');page.locator('#columns').fill('0');page.locator('#model-file').set_input_files({'name':'rejected-view.obj','mimeType':'text/plain','buffer':obj.encode()});page.wait_for_function('document.getElementById("model-status").dataset.error==="true"');self.assertTrue(page.evaluate('()=>{const a=nativeLab.scene.snapshot(),b=nativeLab.scene.render().bytes;return a.length===modelSaved.length&&a.every((v,i)=>v===modelSaved[i])&&b.every((v,i)=>v===modelFrame[i]);}'));page.locator('#columns').fill('80');page.locator('#model-up').select_option('Z');page.locator('#model-original').click();page.evaluate('nativeLab.hold()');self.assertTrue(page.evaluate('nativeLab.scene.modelRecords().some((v,i)=>v!==originalModelRecords[i])'));self.assertEqual(page.evaluate('nativeLab.scene.info().sourceModel.triangles'),4608);page.evaluate('window.originalSizeRecords=nativeLab.scene.modelRecords()');page.locator('#model-size').fill('30');page.locator('#model-original').click();page.evaluate('nativeLab.hold()');sizes=page.evaluate('()=>{function bound(a){const v=new DataView(a.buffer,a.byteOffset,a.byteLength);let maximum=0;for(let at=0;at<a.length;at+=40)for(let k=0;k<36;k+=4)maximum=Math.max(maximum,Math.abs(v.getInt32(at+k,true)));return maximum;}return[bound(originalSizeRecords),bound(nativeLab.scene.modelRecords())]}');self.assertGreater(sizes[0],0);self.assertLessEqual(abs(sizes[0]-sizes[1]*2),1);proof['size60And30CoordinateBounds']=sizes;page.locator('#model-size').fill('60');page.locator('#model-original').click();page.evaluate('nativeLab.hold()');self.assertFalse(errors)
   if os.environ.get('NOCTURNE_MODEL_UI_EVIDENCE'):
    path=Path(os.environ['NOCTURNE_MODEL_UI_EVIDENCE']);path.mkdir(parents=True,exist_ok=True);(path/'browser-proof.json').write_text(json.dumps(proof,indent=2));page.locator('#canvas').screenshot(path=str(path/'orbital-loom-z-up.png'))
   browser.close()
 def test_study_choices_beside_or_below_visible_canvas_and_draft_retained(self):
  with sync_playwright()as pw:
   browser=pw.chromium.launch(headless=True);page=browser.new_page(viewport={'width':1440,'height':900});page.goto(Path(os.environ.get('NOCTURNE_MODEL_GALLERY_PATH',ROOT/'Nocturne-Test-Harness.html')).resolve().as_uri());page.wait_for_function('window.nativeLab');page.evaluate('nativeLab.hold()');page.locator('#draft').fill('Retained model draft e\u0301 🪶');page.locator('#draft').dispatch_event('input')
   bounds=[]
   for width,height in [(1440,900),(390,844),(1200,500),(760,420)]:
    with self.subTest(width=width,height=height):
     page.set_viewport_size({'width':width,'height':height});page.wait_for_timeout(100);page.locator('.study-controls').evaluate('(e)=>e.scrollTop=0');canvas=page.locator('#canvas').bounding_box();self.assertIsNotNone(canvas);self.assertGreater(canvas['width'],0);self.assertGreater(canvas['height'],0);self.assertGreaterEqual(canvas['x'],0);self.assertGreaterEqual(canvas['y'],0);self.assertLessEqual(canvas['x']+canvas['width'],width+.1);self.assertLessEqual(canvas['y']+canvas['height'],height+.1)
     for selector in ['#scenes','#attract']:
      choice=page.locator(selector).bounding_box();self.assertTrue(choice['x']>=canvas['x']+canvas['width']-.1 or choice['y']>=canvas['y']+canvas['height']-.1,(selector,canvas,choice));self.assertGreaterEqual(choice['x'],0);self.assertLessEqual(choice['x']+choice['width'],width+.1)
     bounds.append({'viewport':{'width':width,'height':height},'canvas':canvas,'study':page.locator('#scenes').bounding_box(),'rotation':page.locator('#attract').bounding_box()})
     self.assertEqual(page.locator('#draft').input_value(),'Retained model draft e\u0301 🪶');self.assertEqual(page.evaluate('nativeLab.scene.info().prompt.text'),'Retained model draft e\u0301 🪶')
   if os.environ.get('NOCTURNE_MODEL_UI_EVIDENCE'):
    path=Path(os.environ['NOCTURNE_MODEL_UI_EVIDENCE']);path.mkdir(parents=True,exist_ok=True);(path/'control-placement.json').write_text(json.dumps(bounds,indent=2));page.screenshot(path=str(path/'short-controls.png'));page.set_viewport_size({'width':1440,'height':900});page.wait_for_timeout(100);page.screenshot(path=str(path/'wide-controls.png'))
   browser.close()
if __name__=='__main__':unittest.main()
